function renderLogsFeed() {
  const feedContainer = document.getElementById('logs-right-feed');
  const countSpan = document.getElementById('total-logs-count');
  const searchInput = document.getElementById('quick-plate-search');
  const searchQuery = searchInput ? searchInput.value.trim().toUpperCase() : '';

  if (!feedContainer) return;

  let filtered = logsList.filter(item => {
    if (currentLogFeedFilter === 'bolo' && item.type !== 'bolo') return false;
    if (currentLogFeedFilter === 'vehicle' && item.type !== 'note' && item.type !== 'vehicle') return false;
    if (currentLogFeedFilter === 'cite' && item.type !== 'citation' && item.type !== 'arrest') return false;

    if (searchQuery) {
      const matchPlate = item.plate.includes(searchQuery);
      const matchVehicle = item.vehicle.toUpperCase().includes(searchQuery);
      const matchSubject = item.subject.toUpperCase().includes(searchQuery);
      const matchDesc = item.description.toUpperCase().includes(searchQuery);
      if (!matchPlate && !matchVehicle && !matchSubject && !matchDesc) return false;
    }
    return true;
  });

  if (countSpan) countSpan.textContent = `${filtered.length} Record${filtered.length === 1 ? '' : 's'}`;

  if (filtered.length === 0) {
    feedContainer.innerHTML = `
      <div class="p-6 bg-slate-900/40 border border-slate-800 rounded-xl text-center text-xs text-slate-500">
        No matching records found.
      </div>
    `;
    return;
  }

  let html = '';
  filtered.forEach(item => {
    let badgeColor = 'bg-blue-600/20 text-blue-400 border-blue-500/30';
    let icon = '📌';
    let title = item.secondary;
    if (item.type === 'bolo') {
      badgeColor = 'bg-red-600/20 text-red-400 border-red-500/30';
      icon = '🔴';
      title = `BOLO: ${item.secondary}`;
    } else if (item.type === 'citation') {
      badgeColor = 'bg-amber-600/20 text-amber-400 border-amber-500/30';
      icon = '📝';
      title = `Citation: ${item.secondary}`;
    } else if (item.type === 'arrest') {
      badgeColor = 'bg-purple-600/20 text-purple-400 border-purple-500/30';
      icon = '🔒';
      title = `Arrest: ${item.secondary}`;
    } else if (item.type === 'note') {
      badgeColor = 'bg-teal-600/20 text-teal-400 border-teal-500/30';
      icon = '🚗';
      title = `Vehicle Log: ${item.secondary}`;
    }

    const dateStr = new Date(item.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });

    html += `
      <div class="bg-slate-900/80 border border-slate-800/80 rounded-xl p-3 text-xs space-y-2 relative group">
        <div class="flex items-center justify-between">
          <span class="font-mono font-bold bg-slate-800 text-slate-200 px-2 py-0.5 rounded border border-slate-700">${item.plate}</span>
          <span class="text-[10px] font-mono text-slate-400">${dateStr}</span>
        </div>
        <div class="flex items-center space-x-1.5">
          <span class="px-2 py-0.5 rounded text-[10px] font-bold border ${badgeColor}">${icon} ${title}</span>
        </div>
        <p class="text-slate-300 text-[11px] leading-relaxed">${item.description}</p>
        <div class="flex items-center justify-between pt-1 border-t border-slate-800/60 text-[10px] text-slate-400">
